CREATE TRIGGER beam_quick_ru_insert AFTER INSERT ON MisckeyConfigFuncDB WHEN (NEW.id=3 AND NEW.icon='artificial_correction' AND NEW.name='手动梯形校正') OR (NEW.id=4 AND NEW.icon='scale' AND NEW.name='缩放与位移') OR (NEW.id=5 AND NEW.icon='auto_focus' AND NEW.name='自动对焦') OR (NEW.id=8 AND NEW.icon='signal_source' AND NEW.name='信号源') OR (NEW.id=9 AND NEW.icon='network' AND NEW.name='网络') OR (NEW.id=10 AND NEW.icon='bluetooth' AND NEW.name='蓝牙') OR (NEW.id=11 AND NEW.icon='kid_model' AND NEW.name='儿童模式') OR (NEW.id=12 AND NEW.icon='xgimi_wall' AND NEW.name='任意门') OR (NEW.id=14 AND NEW.icon='u_disk' AND NEW.name='U盘') OR (NEW.id=16 AND NEW.icon='xgimi_music' AND NEW.name='音乐控件') OR (NEW.id=18 AND NEW.icon='screen_rotation' AND NEW.name='画面旋转') OR (NEW.id=23 AND NEW.icon='one_click_correction' AND NEW.name='自动梯形校正') OR (NEW.id=34 AND NEW.icon='energy_mode' AND NEW.name='节能模式') BEGIN UPDATE MisckeyConfigFuncDB SET name=CASE NEW.id WHEN 3 THEN 'Ручная трапеция' WHEN 4 THEN 'Масштаб' WHEN 5 THEN 'Автофокус' WHEN 8 THEN 'Источник' WHEN 9 THEN 'Сеть' WHEN 10 THEN 'Bluetooth' WHEN 11 THEN 'Детский' WHEN 12 THEN 'Заставки' WHEN 14 THEN 'USB' WHEN 16 THEN 'Музыка' WHEN 18 THEN 'Поворот' WHEN 23 THEN 'Автокорр.' WHEN 34 THEN 'Экорежим' ELSE name END WHERE id=NEW.id; END

CREATE TRIGGER beam_quick_ru_update AFTER UPDATE OF name ON MisckeyConfigFuncDB WHEN (NEW.id=3 AND NEW.icon='artificial_correction' AND NEW.name='手动梯形校正') OR (NEW.id=4 AND NEW.icon='scale' AND NEW.name='缩放与位移') OR (NEW.id=5 AND NEW.icon='auto_focus' AND NEW.name='自动对焦') OR (NEW.id=8 AND NEW.icon='signal_source' AND NEW.name='信号源') OR (NEW.id=9 AND NEW.icon='network' AND NEW.name='网络') OR (NEW.id=10 AND NEW.icon='bluetooth' AND NEW.name='蓝牙') OR (NEW.id=11 AND NEW.icon='kid_model' AND NEW.name='儿童模式') OR (NEW.id=12 AND NEW.icon='xgimi_wall' AND NEW.name='任意门') OR (NEW.id=14 AND NEW.icon='u_disk' AND NEW.name='U盘') OR (NEW.id=16 AND NEW.icon='xgimi_music' AND NEW.name='音乐控件') OR (NEW.id=18 AND NEW.icon='screen_rotation' AND NEW.name='画面旋转') OR (NEW.id=23 AND NEW.icon='one_click_correction' AND NEW.name='自动梯形校正') OR (NEW.id=34 AND NEW.icon='energy_mode' AND NEW.name='节能模式') BEGIN UPDATE MisckeyConfigFuncDB SET name=CASE NEW.id WHEN 3 THEN 'Ручная трапеция' WHEN 4 THEN 'Масштаб' WHEN 5 THEN 'Автофокус' WHEN 8 THEN 'Источник' WHEN 9 THEN 'Сеть' WHEN 10 THEN 'Bluetooth' WHEN 11 THEN 'Детский' WHEN 12 THEN 'Заставки' WHEN 14 THEN 'USB' WHEN 16 THEN 'Музыка' WHEN 18 THEN 'Поворот' WHEN 23 THEN 'Автокорр.' WHEN 34 THEN 'Экорежим' ELSE name END WHERE id=NEW.id; END
